-- 1672 events from ESPN keyEvents

-- Bump SERIAL sequences past the explicit IDs we inserted
SELECT setval(pg_get_serial_sequence('paises', 'id'), (SELECT COALESCE(MAX(id), 1) FROM Paises));
SELECT setval(pg_get_serial_sequence('selecoes', 'id'), (SELECT COALESCE(MAX(id), 1) FROM Selecoes));
SELECT setval(pg_get_serial_sequence('edicoescopa', 'id'), (SELECT COALESCE(MAX(id), 1) FROM EdicoesCopa));
SELECT setval(pg_get_serial_sequence('fases', 'id'), (SELECT COALESCE(MAX(id), 1) FROM Fases));
