SELECT setval(pg_get_serial_sequence('estadios', 'id'), (SELECT COALESCE(MAX(id), 1) FROM Estadios));
SELECT setval(pg_get_serial_sequence('grupos', 'id'), (SELECT COALESCE(MAX(id), 1) FROM Grupos));
SELECT setval(pg_get_serial_sequence('partidas', 'id'), (SELECT COALESCE(MAX(id), 1) FROM Partidas));
SELECT setval(pg_get_serial_sequence('arbitros', 'id'), (SELECT COALESCE(MAX(id), 1) FROM Arbitros));
SELECT setval(pg_get_serial_sequence('jogadores', 'id'), (SELECT COALESCE(MAX(id), 1) FROM Jogadores));
